    private string _output="";private readonly List<object> _checks=new(),_provenance=new();
    private void Check(bool condition,string name){_checks.Add(new{name,passed=condition});if(!condition)throw new InvalidOperationException(name);}
    public override async void _Ready()
    {
        string? error=null;
        try
        {
            _output=OS.GetCmdlineUserArgs().Single(a=>a.StartsWith("--validation-output="))[20..];Directory.CreateDirectory(_output);Check(DisplayServer.GetName()!="headless","Actual graphical Godot display");
            foreach(var size in new[]{new Vector2I(800,600),new Vector2I(1920,1080)}){await Primary(size);await SafetyResume(size);await Scale(size);await OfficerEncounter(size,"harl",false);await OfficerEncounter(size,"wenth",true);await Founder(size);}
        }
        catch(Exception failure){error=failure.ToString();GD.PrintErr(error);}
        finally{if(_output.Length>0)File.WriteAllText(Path.Combine(_output,"results.json"),JsonSerializer.Serialize(new{scenario="Fleet",passed=error is null,error,method="Actual native Godot controls/signals; no physical input or human readability claim",checks=_checks,provenance=_provenance},new JsonSerializerOptions{WriteIndented=true}));GetTree().Quit(error is null?0:1);}
    }
    private async Task Click(Control control)
