        Check(session.State.Empires[0].Fleets!.Requests.Count==3,"Several finite requests without visiting map objects");await Click(fleet,"FleetOpenOfficers");var officer=Descendants<OfficerDetailDialog>(screen).Single();Check(Named<Label>(officer,"OfficerDetails").Text.Contains("XP 0/30",StringComparison.Ordinal),"Scale service record does not invent earned XP");await Shot(officer,"scale-career-"+size.X);await Close(officer);string file=Path.Combine(_output,$"labelled-scale-{size.X}.json");session.Save(file);var loaded=SaveGame.ReadFile(file);Check(loaded.Succeeded&&SaveGame.Serialize(loaded.Game!.Content,loaded.Game.State)==Snapshot(session),"Labelled scale save/reload exact");RemoveChild(screen);screen.QueueFree();await Frames(this);
    }
    private async Task OfficerEncounter(Vector2I size,string species,bool researched)
    {
        GetTree().Root.Size=size;var c=CompleteContent();var generated=GalaxyGenerator.CreateNewGame(c,new("small",42,8,species,CrisesEnabled:false,AmebasEnabled:true));Check(generated.Succeeded,"Officer encounter supplement base");var s=generated.State!;var owner=s.Empires[0].Id;var ship=s.Vessels[0];var group=CommandProcessor.Execute(c,s,new FleetCommand(owner,0,new FleetAction.Create("Encounter command",ImmutableArray.Create(ship.Id))));Check(group.Accepted,"Pre-session ordinary named fleet");var board=CommandProcessor.Execute(c,group.State,new OfficerCommand(owner,0,new OfficerAction.AssignFlagship(new(1),new(1))));Check(board.Accepted,"Pre-session physical officer assignment");s=board.State;s.Turn=10;ship=s.FindVessel(ship.Id)!;var habitat=s.Scouting!.Habitat!;ship.StationaryStarId=habitat.Star;ship.AmebaEncounter=new(){Number=1,HabitatId=habitat.Id,ArrivalTurn=10};s.Empires[0].Scouting!.NextEncounterNumber=2;s.Empires[0].Scouting!.KnownHabitats.Add(new(habitat.Id,habitat.Star,10));if(researched){s.Empires[0].KnownTechnologyIds.AddRange(new[]{"measurement_methods","industrial_coordination","command_recovery"});s.Empires[0].KnownTechnologyIds.Sort(StringComparer.Ordinal);}ObservationUpdater.Refresh(s,10);Check(GameStateValidator.Validate(c,s).Count==0,"Labelled officer encounter state validates");
        _provenance.Add(new{source="Labelled pre-session Warning and optional researched equipment, ordinary pre-session command assignment; no generated discovery, luck or research claim",species,researched,resolution=size.X,liveOutcomeInjections=0});var session=new GameSession(c,s);var screen=Screen(session,owner,_output);screen.FleetPreferencesPath=Path.Combine(_output,$"encounter-fleet-{species}-{size.X}.json");screen.ScoutPreferencesPath=Path.Combine(_output,$"encounter-scout-{species}-{size.X}.json");new OpenAntares.Game.Presentation.ScoutNotificationPreferences(OpenAntares.Game.Presentation.ScoutDisplayLevel.Digest).Save(screen.ScoutPreferencesPath);AddChild(screen);await Frames(this);await Click(screen,"OpenFleetCommand");var fleet=Descendants<FleetCommandDialog>(screen).Single();await Select(Named<ItemList>(fleet,"FleetShipList"),0);await Click(fleet,"FleetInspectShip");await Click(screen,"InspectScoutEncounter");var scouting=Named<AcceptDialog>(screen,"ScoutOverview");var text=string.Join("\n",Descendants<Label>(scouting).Select(l=>l.Text));Check(text.Contains(species=="wenth"?"without an officer random draw":"officer recovery is 50%",StringComparison.Ordinal),"Material officer recovery/link consequence shown before acknowledgement");
        string initial=Snapshot(session);await Shot(scouting,$"officer-encounter-{species}-{size.X}");Check(Snapshot(session)==initial,"Officer consequence display makes no draw or acknowledgement");await Click(scouting,"ScoutStudy");await Confirm(scouting,"ScoutConfirmation");text=string.Join("\n",Descendants<Label>(scouting).Select(l=>l.Text));Check(text.Contains("+8 XP",StringComparison.Ordinal),"Conditional study XP and passive unlock consequence displayed");Check(session.State.Empires[0].Fleets!.RecoveryRollCount==0&&session.State.Empires[0].Scouting!.RiskRollCount==0,"Queuing study never rolls officer or hull randomness");RemoveChild(screen);screen.QueueFree();await Frames(this);
    }
    private async Task Founder(Vector2I size)
    {
        GetTree().Root.Size=size;var c=CompleteContent();var generated=GalaxyGenerator.CreateNewGame(c,new("small",42,8,"wenth",CrisesEnabled:false,AmebasEnabled:false));Check(generated.Succeeded,"Founder supplement base");var s=generated.State!;var owner=s.Empires[0].Id;var ship=s.Vessels[0];var role=c.Vessels.Values.Single(v=>v.CanFoundColony&&c.Species["wenth"].AllowedVesselIds.Contains(v.Id));ship.RoleId=role.Id;ship.CarriedPopulation=role.EmbarkPopulation;ship.Scout=null;s.Colonies[0].Population-=ship.CarriedPopulation;s.Colonies[0].Workforce=new(s.Colonies[0].Population,0,0);
        var target=s.Planets.First(p=>!s.Colonies.Any(col=>col.PlanetId==p.Id)&&c.PlanetTypes[p.PlanetTypeId].Colonizable&&c.PlanetTypes[p.PlanetTypeId].SupportPerWorker>0&&OpenAntares.Simulation.Species.SpeciesRules.HabitatAllowed(c,s,owner,p.EnvironmentId!,role.FoundsSealedHabitat?OpenAntares.Simulation.Species.HabitatModes.Sealed:OpenAntares.Simulation.Species.HabitatModes.Native));
        var group=CommandProcessor.Execute(c,s,new FleetCommand(owner,0,new FleetAction.Create("Founding command",ImmutableArray.Create(ship.Id))));Check(group.Accepted,"Pre-session founder group");var board=CommandProcessor.Execute(c,group.State,new OfficerCommand(owner,0,new OfficerAction.AssignFlagship(new(1),new(1))));Check(board.Accepted,"Whole-body source appointment boards physical flagship");s=board.State;s.FindVessel(ship.Id)!.StationaryStarId=target.StarId;ObservationUpdater.Refresh(s,0);Check(GameStateValidator.Validate(c,s).Count==0,"Labelled co-located founder supplement validates");var sourceBody=s.Empires[0].Fleets!.Officers[0].SourceBody;
        _provenance.Add(new{source="Labelled pre-session paid colony-body expedition/cargo, co-location and surveyed target; actual founding uses separate planet control",species="wenth",resolution=size.X,liveOutcomeInjections=0});var session=new GameSession(c,s);var screen=Screen(session,owner,_output);screen.FleetPreferencesPath=Path.Combine(_output,$"founder-fleet-{size.X}.json");AddChild(screen);await Frames(this);await Click(screen,"OpenFleetCommand");var fleet=Descendants<FleetCommandDialog>(screen).Single();await Select(Named<ItemList>(fleet,"FleetShipList"),0);await Click(fleet,"FleetInspectShip");await Click(Descendants<Button>(screen).Single(b=>b.Text=="Select planet "+target.Orbit));await Click(Descendants<Button>(screen).Single(b=>b.Text=="Found colony"));Check(session.State.FindVessel(ship.Id)!.PendingFounding==target.Id,"Explicit separate planet founding command");await End(screen,session);var o=session.State.Empires[0].Fleets!.Officers[0];Check(o.Status==OfficerStatus.Posted&&o.SourceBody==sourceBody&&o.PostedColony==session.State.Colonies.Single(col=>col.PlanetId==target.Id).Id&&session.State.Empires[0].Fleets!.RecoveryRollCount==0,"Native founding posts officer with source identity and no loss roll");await Click(screen,"OpenFleetCommand");await Click(fleet,"FleetOpenOfficers");var officers=Descendants<OfficerDetailDialog>(screen).Single();Check(Named<Label>(officers,"OfficerDetails").Text.Contains("Whole source body",StringComparison.Ordinal),"Wenth service detail uses whole-body language");await Click(officers,"OfficerToggleTurnDetails");await Shot(officers,"wenth-founder-record-"+size.X);RemoveChild(screen);screen.QueueFree();await Frames(this);
    }
